package com.chubb.apac.claims.modulith.claim.repository;
import com.chubb.apac.claims.modulith.claim.model.Claim;import com.chubb.apac.claims.modulith.common.enums.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class ClaimRepositoryTest {@Autowired ClaimRepository repository;@Test void findsByOwner(){Claim c=new Claim();c.setClaimId("CLM-1");c.setIncidentId("INC-1");c.setClaimantId("U1");c.setStatus(ClaimStatus.REPORTED);c.setProductType(ProductType.MOTOR);c.setMarket(Market.SG);c.setCreatedBy("U1");c.setUpdatedBy("U1");repository.saveAndFlush(c);assertThat(repository.findByClaimIdAndClaimantId("CLM-1","U1")).isPresent();assertThat(repository.findByClaimIdAndClaimantId("CLM-1","U2")).isEmpty();}}
